"""Self-contained ten-section case review; all model views come from NBT."""
from pathlib import Path
import base64,csv,html,json,shutil
CASE=Path(__file__).resolve().parents[1];ROOT=CASE.parents[1]
OUT=ROOT/'deliverables/nanshan_cloud_v1';RUN='V1_r04';STEM='Nanshan_Cloud_HAF_V1'
LABEL={'overview':'全景 · 日间','night':'全景 · 夜间','front':'正面 +Z','right':'右侧 +X','rear':'背面 −Z','left':'左侧 −X','hills':'退台与幕墙','underside':'悬挑底面','base':'柱廊与场地','lobby':'入口与二层通道','top':'俯视平面','crown':'屋顶设备区','section':'剖切 · 窗后空间'}
def uri(p,mime='image/png'):return 'data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()
def esc(v):return html.escape(str(v))
JS=r'''
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);let view='overview';
function dl(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function zoom(src,title){$('zoomImg').src=src;$('zoomTitle').textContent=title;$('zoomImg').style.maxWidth='100%';$('zoom').showModal()}
$('zoomClose').onclick=()=>$('zoom').close();$('zoomActual').onclick=()=>$('zoomImg').style.maxWidth=$('zoomImg').style.maxWidth==='none'?'100%':'none';
document.querySelectorAll('[data-zoom]').forEach(e=>e.onclick=()=>zoom(e.src,e.alt));
function show(){const v=D.views[view];$('mainImage').src=v.src;$('mainImage').alt=v.label;$('imageTitle').textContent=v.label;$('imageNote').textContent=view==='section'?'仅预览剖切，交付文件保持完整；室内为程序化窗后层。':view==='night'?'灯位来自最终文件；光晕与色温为离线近似，不能代替游戏夜景。':view==='rear'||view==='left'?'已补全围护；后部平台及第三塔相对高度尚待更多照片或平面校准。':'本地工作轴，不代表已核实地理北。点击可看原始大图。';$('viewButtons').replaceChildren();Object.entries(D.views).forEach(([k,v])=>{let b=document.createElement('button');b.textContent=v.label;b.className=k===view?'active':'';b.onclick=()=>{view=k;show()};$('viewButtons').append(b)})}
$('mainImage').onclick=()=>zoom($('mainImage').src,$('mainImage').alt);
function compare(){const v=D.comparisons[$('comparePart').value];$('beforeImage').src=v.before;$('afterImage').src=v.after;$('beforeLabel').textContent=v.beforeLabel;$('afterLabel').textContent='V1 / r04 · 交付基线';$('compareNote').textContent=v.note}
$('comparePart').onchange=compare;['beforeImage','afterImage'].forEach(id=>$(id).onclick=()=>zoom($(id).src,id==='beforeImage'?'本轮原型':'交付基线'));
let feedback=[];try{const x=JSON.parse(localStorage.getItem('haf-nanshan-cloud-v1-feedback')||'[]');if(Array.isArray(x))feedback=x}catch(e){}
for(const c of D.components){let o=document.createElement('option');o.value=c;o.textContent=c;$('fbPart').append(o)}
for(const [k,v]of Object.entries(D.views)){let o=document.createElement('option');o.value=k;o.textContent=v.label;$('fbView').append(o)}
function draw(){const list=$('feedbackList');list.replaceChildren();feedback.forEach((r,i)=>{const el=document.createElement('div');el.className='feedback-row';let t=document.createElement('div');t.textContent=(i+1)+'. '+r.component_id+' / '+r.view_id+'\n'+r.problem+'\n希望：'+r.requested_change;el.append(t);let b=document.createElement('button');b.type='button';b.textContent='删除此条';b.onclick=()=>{feedback.splice(i,1);save()};el.append(b);list.append(el)});$('feedbackCount').textContent=feedback.length+' 条待讨论反馈'}
function save(){try{localStorage.setItem('haf-nanshan-cloud-v1-feedback',JSON.stringify(feedback));$('fbStatus').textContent='已保存在当前浏览器。导出 JSON 后可交回项目。'}catch(e){$('fbStatus').textContent='无法本地保存，请立即导出 JSON。'}draw()}
$('feedbackForm').onsubmit=e=>{e.preventDefault();feedback.push({case:'nanshan_cloud',baseline_run:'V1_r04',baseline_nbt_sha256:D.hash,component_id:$('fbPart').value,view_id:$('fbView').value,problem:$('fbProblem').value.trim(),requested_change:$('fbChange').value.trim(),evidence_url:$('fbEvidence').value.trim(),priority:$('fbPriority').value});save();$('fbProblem').value='';$('fbChange').value=''};
$('exportFeedback').onclick=()=>dl('Nanshan_Cloud_HAF_V1_Feedback.json',JSON.stringify({schema_version:1,status:'user feedback; not executed',items:feedback},null,2));
$('downloadMaterials').onclick=()=>dl('Nanshan_Cloud_HAF_V1_Materials.csv','\ufeff'+D.material_csv,'text/csv;charset=utf-8');
show();compare();draw();
'''
def main():
    OUT.mkdir(parents=True,exist_ok=True);run=CASE/'runs'/RUN;prev=CASE/'review/previews'/RUN
    m=json.loads((run/'manifest.json').read_text());qa=json.loads((CASE/'validation/acceptance.json').read_text());imp=json.loads((run/'import_pack/import_manifest.json').read_text());ev=json.loads((CASE/'research/component_evidence.json').read_text());imgs=json.loads((CASE/'research/images.json').read_text())
    views={k:{'src':uri(prev/(k+'.png')),'label':v} for k,v in LABEL.items()}
    comps={
      'facade':{'before':uri(CASE/'review/previews/V1_r02/hills.png'),'after':views['hills']['src'],'beforeLabel':'r02 · 宽木肋与玻璃断口','note':'同一相机：竖向肋条改用铁栅栏；横向压边和窗间板移到玻璃外，保留玻璃连续性。'},
      'roof':{'before':uri(CASE/'review/previews/V1_r03/top.png'),'after':views['top']['src'],'beforeLabel':'r03 · 屋顶混入窗后家具','note':'同一相机：屋顶设备区排除合成办公室，保留机械设备和开敞围栏。设备布置本身仍属估算。'}}
    data={'views':views,'comparisons':comps,'hash':m['sha256'],'components':[c['component_id'] for c in ev['components']],'material_csv':(run/'materials.csv').read_text(encoding='utf-8-sig')}
    evidence_rows=''.join('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in [c['component_id'],c['observation'],', '.join(c['image_ids']),c['consumer'],c['uncertainty']])+'</tr>' for c in ev['components'])
    selected=[r for r in imgs if r.get('selected') and r.get('viewed')]
    source_rows=''.join(f'<tr><td>{esc(r["image_id"])}</td><td>{esc(r.get("view","未分类"))}</td><td>{esc(r.get("observation",""))}</td><td><a href="{esc(r["page_url"])}" target="_blank" rel="noopener">来源页</a> · <a href="{esc(r["url"])}" target="_blank" rel="noopener">原图</a></td></tr>' for r in selected)
    rows=list(csv.DictReader(data['material_csv'].splitlines()));rows.sort(key=lambda r:int(r['count']),reverse=True)
    material_rows=''.join(f'<tr><td>{esc(r["block_id"].removeprefix("minecraft:"))}</td><td>{int(r["count"]):,}</td></tr>' for r in rows[:10])
    photos=[]
    for iid,title in [('img-002','运营方航拍 · 建成形态'),('img-022','正面夜景 · 灯光与高塔关系')]:
        r=next(v for v in imgs if v['image_id']==iid);f=CASE/'research'/r['local_file']
        body=f'<img data-zoom src="{uri(f,"image/jpeg")}" alt="{title}">' if f.exists() else '<p>此源码包不重复分发原始照片，请从下方来源打开。</p>'
        photos.append(f'<article class="card"><h3>{title}</h3>{body}<p class="small"><a href="{esc(r["page_url"])}" target="_blank" rel="noopener">{iid} · 原始来源</a>。图片版权归原权利人，展示用于本次参考核对；不作为已授权模型训练数据。灯光奖项页未完整取回，采用的是已查看的原始照片。</p></article>')
    schem=run/'import_pack'/(STEM+'.schem');css=(CASE/'review/assets/style.css').read_text()
    body='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>南山云科技大厦 · HAF V1</title><style>'''+css+'''</style></head><body>
<header><small>HAIBARA’S ARCHITECT / BUILDING STUDY</small><h1>南山云科技大厦</h1><p>HAF 0.2 · V1 / r04<br>三组错位塔体、阶梯平台与双重幕墙语言。</p></header>
<nav><a href="#result">成果</a><a href="#gallery">13 张大图</a><a href="#sources">真实参考</a><a href="#compare">修改对照</a><a href="#materials">材料 / 下载</a><a href="#feedback">反馈</a></nav><main>
<section id="result"><h2><b>01 / 本轮成果</b>让竖向塔体与横向退台同时成立</h2><div class="three"><div class="metric"><span class="value">235 格</span>最高塔体 · 约 1 格/米</div><div class="metric"><span class="value">'''+f'{m["non_air_blocks"]:,}'+'''</span>非空气方块 · 含局部场地</div><div class="metric"><span class="value">13 张</span>全景 / 四面 / 近景 / 夜景 / 剖切</div></div><p>本轮完成塔体、四组阶梯平台、细竖肋、连续玻璃、悬挑底面、开敞屋顶、首层柱廊、局部二层通道和入口景观。场地为 140 × 140 格范围内的近似。</p><p class="note">全部模型图由交付 NBT 独立读回。当前是未加载资源包纹理的几何预览，尚未进入 Minecraft 实测。</p></section>
<section id="gallery"><h2><b>02 / 大图品鉴</b>按部位放大检查</h2><div id="viewButtons" class="thumbs"></div><div class="viewer"><img id="mainImage" alt="建筑模型"><div class="caption"><strong id="imageTitle"></strong><div id="imageNote" class="muted"></div></div></div></section>
<section id="sources"><h2><b>03 / 建筑与图源</b>先区分建成照片与早期方案</h2><p>对象为深圳留仙洞万科云城六期 1 栋。<a href="https://www.cncarbonneutral.com/Dgus/Detail?Id=2792" target="_blank" rel="noopener">2025 年运营方提交的案例</a>记载高度 234.54 米，本轮取整至 235 格。<a href="https://old.skyscraper.org/EXHIBITIONS/WOHA/vanke.php" target="_blank" rel="noopener">早期设计展</a>和 2015 年方案中的 246–250 米不直接替换建成尺度。</p><div class="two photo-pair">'''+''.join(photos)+'''</div><p>本轮使用不限数量的 HA 图片研究。候选、成功下载、实际查看和最终采用分别登记；共 '''+str(len(imgs))+''' 条候选记录，其中 '''+str(len(selected))+''' 条“已查看并采用”。三维模型路线本次未取得可用文件，采用纯图片解释。</p><details><summary>打开参考盒索引与来源</summary><p>按整体、退台、立面、底部、屋顶和夜景组织。方向为工作坐标关联；没有完成相机恢复、正射拼接或自动三维分割。</p><div class="scroll"><table class="source-index"><tr><th>ID</th><th>类型</th><th>已查看的内容</th><th>来源</th></tr>'''+source_rows+'''</table></div></details><p class="muted">公开方案只取得前 5 张预览；目录不能当作完整施工图。政府连廊资料属于规划/招标信息，未作为已经建成的桥梁加入模型。</p></section>
<section id="logic"><h2><b>04 / 生成逻辑</b>构件先分层，再汇总成方块</h2><div class="three"><article class="card"><h3>竖向塔体</h3><p>三座矩形塔与内退核心分开；灰色玻璃片加铁栅栏细肋，保留深槽。高塔对近等高，第三塔相对高度暂估。</p></article><article class="card"><h3>阶梯平台</h3><p>四个标高组，每组以七级方块化退台表达。浅蓝/白色玻璃、薄压边、绿化、深色底面分层生成。</p></article><article class="card"><h3>底部与屋顶</h3><p>首层留通道、石材柱和门厅，局部二层玻璃栏杆。平屋顶留设备凹区，排除办公家具侵入。</p></article></div><details><summary>构件证据 → 参数 / 代码 → 尚存缺口</summary><div class="scroll"><table><tr><th>构件</th><th>判断</th><th>证据图</th><th>实际消费者</th><th>近似与待核实</th></tr>'''+evidence_rows+'''</table></div></details></section>
<section id="compare"><h2><b>05 / 自检修改</b>同一相机，保留修改原因</h2><div class="toolbar"><label for="comparePart">选择部位</label><select id="comparePart"><option value="facade">竖肋与玻璃连续性</option><option value="roof">屋顶与内饰排除</option></select></div><div class="two compare"><article><h3 id="beforeLabel"></h3><img id="beforeImage" alt="自检前"></article><article><h3 id="afterLabel"></h3><img id="afterImage" alt="修正后"></article></div><p id="compareNote"></p><p class="muted">r01–r03 为保存的本轮原型，r04 为交付基线；不把内部修订当作不同引擎的公平 A/B 实验。</p></section>
<section id="lighting"><h2><b>06 / 灯光与窗后空间</b>固定灯带与室内占灯分开</h2><p>参考夜景布置平台底缘和主塔顶缘暖色灯带，并在局部竖肋附近补光。窗后房间以稳定 ID 和种子决定风格、亮暗及冷暖灯，避免整面等距全亮。</p><div class="two"><article class="card"><h3>可复用的规则</h3><p>暖色荧石与冷色海晶灯并用；室内家具优先检查净空；底面保留不发光的结构分格；屋顶设备区禁止窗后内饰。</p></article><article class="card"><h3>保留的边界</h3><p>办公室是合成窗后层，不是真实户型。夜景曝光与色温不能直接换算成灯数；本次未放置灯位未经确认的航空障碍灯。</p></article></div><p class="note">原版 Minecraft 不按此预览传播彩色光。玻璃、铁栅栏和活板门在资源包纹理及游戏邻接更新下的效果，需要再验。</p></section>
<section id="materials"><h2><b>07 / 材料与文件</b>从最终方块统计</h2><div class="two"><article class="card"><h3>主要材料</h3><table><tr><th>材料 ID</th><th>数量</th></tr>'''+material_rows+'''</table></article><article class="card"><h3>导出物</h3><p>'''+f'{m["material_types"]} 种材料 ID · {m["state_types"]} 种状态'+'''</p><p><button id="downloadMaterials">下载完整材料 CSV</button></p><p><a class="download" href="'''+uri(schem,'application/octet-stream')+'''" download="'''+schem.name+'''">下载完整 .schem</a></p><p>完整建筑包另含 NBT、'''+str(imp['module_count'])+''' 个分区、模块坐标、精确状态表及 13 张预览。</p><p class="muted">半砖、玻璃片、铁栅栏按其实际方块 ID 计数；这些数量不等于完整实体立方体的数量。</p></article></div></section>
<section id="validation"><h2><b>08 / 验证与缺口</b>文件通过，写实度仍需品鉴</h2><div class="scroll"><table><tr><th>检查层</th><th>结果</th></tr><tr><td>已有引擎测试</td><td>30 项单元测试通过</td></tr><tr><td>本栋独立检查</td><td>'''+str(len(qa['checks']))+''' 项通过：回读、几何空洞、围护采样、屋顶排除、预览来源等</td></tr><tr><td>完整重跑</td><td>相同种子、参数和代码得到相同 NBT 哈希</td></tr><tr><td>Schem 与分包</td><td>独立回读一致；'''+str(imp['module_count'])+''' 个模块拼合后逐坐标/状态一致，最大 '''+f'{imp["module_max_bytes"]:,}'+''' B</td></tr><tr><td>视觉</td><td>人工检查多视角并完成本轮修正；真实还原度待用户评价</td></tr><tr><td>Minecraft</td><td>导入、纹理、碰撞、邻接更新与游戏光照待测</td></tr></table></div><p class="note">最需要继续校准：主塔偏灰蓝的材质观感、过于规律的平台绿化、第三塔高度、真实平面深度、背部退台与连接、夜景常态模式。这里没有自动算出“还原率”。</p><p>当前能补充一种新的构件组合样本，但不能据此认定所有现代建筑都已通用。建议同类规则至少再用一栋独立建筑验证。</p></section>
<section id="import"><h2><b>09 / 导入与复现</b>源码、参数和历史一起保留</h2><p>目标数据版本为 Java 1.21.1；.schem 为 Sponge v3。包围盒 140 × 244 × 140，局部地面 Y=4；默认世界完整包围盒原点 Y 上限为 76。</p><p>模块以同一原点加 offset_xyz 放置，不分别旋转。完整 .schem 含空气；跳过空气或稀疏 NBT 不会清走洞口内的旧方块，宜在空白测试场地导入。兼容性见包内 IMPORT_GUIDE.txt。</p><p>源码包中，params.json 管理尺度与材料，src/build_case.py 管理本栋几何，learning/nanshan_cloud_v1.json 记录可复用规则与失败案例。部分底部和灯位仍是代码常量，不声称全参数化。</p><p class="muted">素材来自公开网页，研究记录保留 URL、哈希及采用状态；源码包不重复分发原始网页和照片。记录规则与案例，不等于训练了一个神经网络模型。</p></section>
<section id="feedback"><h2><b>10 / 下一轮反馈</b>把“哪里不像”落到构件</h2><p>填写后可导出反馈 JSON；只记录待讨论修改，不会自动重建或改写代码。</p><form id="feedbackForm"><div class="feedback-grid"><div><label for="fbPart">构件</label><select id="fbPart"></select></div><div><label for="fbView">视图</label><select id="fbView"></select></div><div><label for="fbPriority">优先级</label><select id="fbPriority"><option value="high">高：形态或结构</option><option value="medium" selected>中：细节表达</option><option value="low">低：后续精修</option></select></div></div><p><label for="fbProblem">具体哪里不像 / 想保留什么</label><textarea id="fbProblem" required></textarea></p><p><label for="fbChange">希望如何调整</label><textarea id="fbChange" required></textarea></p><p><label for="fbEvidence">参考链接（可选）</label><input id="fbEvidence" type="url" placeholder="https://" style="width:100%"></p><button type="submit">保存这条反馈</button> <button type="button" id="exportFeedback">导出反馈 JSON</button></form><p id="fbStatus" class="muted"></p><p id="feedbackCount"></p><div id="feedbackList"></div></section>
</main><footer>HAF 0.2 · 南山云科技大厦 V1 / r04 · 2026-10-23</footer><dialog id="zoom"><div class="zoom-head"><strong id="zoomTitle"></strong><button id="zoomActual">适应 / 原始尺寸</button><button id="zoomClose">关闭</button></div><div class="zoom-scroll"><img id="zoomImg" alt="大图"></div></dialog><script id="data" type="application/json">'''+json.dumps(data,ensure_ascii=False).replace('</',r'<\/')+'''</script><script>'''+JS+'''</script></body></html>'''
    f=OUT/(STEM+'_Review.html');f.write_text(body)
    for n in ['overview','night']:shutil.copy2(prev/(n+'.png'),OUT/(STEM+'_'+n.title()+'.png'))
    print(json.dumps({'file':str(f),'bytes':f.stat().st_size,'views':len(views),'viewed_selected_images':len(selected)},ensure_ascii=False))
if __name__=='__main__':main()
